// WF04 step 2 — collapse N document rows into one item with arrays.
const trigger = $('When called by WF03').first().json || {};
const rows = $input.all().map(i => i.json).filter(r => r && r.session_id);
const sessionId = (rows[0] && rows[0].session_id) || trigger.session_id || '';
const chatId = String(sessionId).split('_')[0] || '';
const fileNames = Array.from(new Set(rows.map(r => r.file_name).filter(Boolean)));
const extractId = (url) => {
  const m = String(url || '').match(/[-\w]{25,}/);
  return m ? m[0] : null;
};
const driveIds = Array.from(new Set(rows.map(r => extractId(r.drive_url)).filter(Boolean)));
return [{ json: { session_id: sessionId, chat_id: chatId, documents: rows, file_names: fileNames, drive_ids: driveIds, doc_count: rows.length } }];

// WF04 step 4 — compose final HTML message per §8.1/§8.2.
// Missing-required types computed INLINE from `template` + `documents` (no _report dependency).
const agg = $('Aggregate Documents').first().json || {};
const sessionId = agg.session_id || '';
const chatId = agg.chat_id || '';
const documents = Array.isArray(agg.documents) ? agg.documents : [];

const httpResp = ($('HTTP: Build ZIP').first() && $('HTTP: Build ZIP').first().json) || {};
const zipUrl = httpResp.zip_url || 'https://drive.google.com/drive/folders/1OvuG8ZTHlvF375Oj0GscdtH0nH8iadRU';
const httpOk = !!httpResp.zip_url;

const templateRows = $('template: Read').all().map(i => i.json);
const detectedTypes = new Set(
  documents
    .filter(d => d && d.detected_type && d.detected_type !== 'unknown')
    .map(d => String(d.detected_type).trim())
);
const requiredTypes = templateRows
  .filter(r => {
    const v = r.is_required;
    return v === true || String(v).toUpperCase() === 'TRUE';
  })
  .map(r => String(r.document_type || '').trim())
  .filter(t => t);
const missingRequired = requiredTypes.filter(t => !detectedTypes.has(t));

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const v = (x) => {
  if (x == null) return '';
  const s = String(x).trim();
  if (s === '' || s === '0' || s === 'null' || s === 'undefined') return '';
  return s;
};

const recognized = documents
  .filter(d => d && d.detected_type && d.detected_type !== 'unknown')
  .map(d => {
    const parts = [];
    const num = v(d.number);
    const dt = v(d.date);
    const am = v(d.amount);
    const co = v(d.contractor);
    if (num) parts.push('№' + num);
    if (dt) parts.push(dt);
    if (am) parts.push(am);
    if (co) parts.push(co);
    const tail = parts.length ? ' (' + esc(parts.join(', ')) + ')' : '';
    return '• ' + esc(d.detected_type) + tail;
  });

const total = documents.length;
const processed = recognized.length;
const nowIso = new Date().toISOString();

let text;
if (missingRequired.length === 0) {
  text =
    '✅ Обработано ' + processed + '/' + total + ' документов.\n\n' +
    '\u{1F4C2} Распознаны:\n' + (recognized.length ? recognized.join('\n') : '—') + '\n\n' +
    'Отсутствуют: —\n\n' +
    '\u{1F5C2} Архив: ' + zipUrl;
} else {
  const missingList = missingRequired.map(m => '• ' + esc(m)).join('\n');
  text =
    '⚠ Обработано ' + processed + '/' + total + ' документов.\n\n' +
    '\u{1F4C2} Распознаны:\n' + (recognized.length ? recognized.join('\n') : '—') + '\n\n' +
    '❌ Отсутствуют (обязательные):\n' + missingList + '\n\n' +
    '\u{1F5C2} Архив: ' + zipUrl;
}

return [{ json: {
  session_id: sessionId,
  chat_id: chatId,
  text,
  zip_url: zipUrl,
  http_ok: httpOk,
  missing_required: missingRequired,
  missing_required_count: missingRequired.length,
  callback_data: 'gen_letter|' + sessionId,
  completed_at: nowIso
}}];
